[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>MedBook — Find and Book Top Doctors Instantly</title>
<meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. Always free for patients.">
<style>
/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #1B1464;
  --navy-light: #2a2080;
  --yellow: #FFD930;
  --yellow-hover: #f0cc1e;
  --white: #FFFFFF;
  --gray-50: #F8F9FC;
  --gray-100: #F0F2F7;
  --gray-200: #E2E5ED;
  --gray-400: #9BA3B5;
  --gray-600: #5A6178;
  --gray-800: #2D3142;
  --teal: #0ABAB5;
  --teal-light: #E6FAF9;
  --green: #22C55E;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 3px rgba(27,20,100,0.06), 0 1px 2px rgba(27,20,100,0.04);
  --shadow-md: 0 4px 12px rgba(27,20,100,0.08), 0 2px 4px rgba(27,20,100,0.04);
  --shadow-lg: 0 12px 32px rgba(27,20,100,0.10), 0 4px 8px rgba(27,20,100,0.06);
  --shadow-xl: 0 20px 48px rgba(27,20,100,0.12), 0 8px 16px rgba(27,20,100,0.06);
  --transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  color: var(--gray-800);
  line-height: 1.6;
  font-size: 16px;
  background: var(--white);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4 { line-height: 1.2; color: var(--navy); font-weight: 700; }
h1 { font-size: clamp(2rem, 5vw, 3.25rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.25rem); letter-spacing: -0.01em; }
h3 { font-size: 1.125rem; }
p { color: var(--gray-600); line-height: 1.7; }
a { color: inherit; text-decoration: none; }

.container { max-width: 1180px; margin: 0 auto; padding: 0 24px; }
.section-label {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal);
  margin-bottom: 12px;
}
.section-title { margin-bottom: 16px; }
.section-subtitle { font-size: 1.0625rem; max-width: 580px; margin: 0 auto 48px; }

/* ===== HEADER ===== */
.header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(27,20,100,0.06);
  transition: box-shadow var(--transition);
}
.header.scrolled { box-shadow: var(--shadow-sm); }
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  height: 68px;
}
.logo {
  display: flex; align-items: center; gap: 8px;
  font-size: 1.375rem; font-weight: 800; color: var(--navy);
}
.logo-icon {
  width: 36px; height: 36px; background: var(--navy);
  border-radius: var(--radius-sm); display: flex;
  align-items: center; justify-content: center;
}
.logo-icon svg { width: 22px; height: 22px; }
.nav-links { display: flex; align-items: center; gap: 8px; }
.nav-link {
  padding: 8px 16px; border-radius: var(--radius-sm);
  font-size: 0.9375rem; font-weight: 500; color: var(--gray-600);
  transition: all var(--transition);
}
.nav-link:hover { color: var(--navy); background: var(--gray-50); }
.nav-link.signup {
  background: var(--navy); color: var(--white);
  padding: 8px 20px; font-weight: 600;
}
.nav-link.signup:hover { background: var(--navy-light); }

/* Hamburger */
.hamburger {
  display: none; width: 44px; height: 44px;
  background: none; border: none; cursor: pointer;
  flex-direction: column; align-items: center; justify-content: center;
  gap: 5px; padding: 10px;
}
.hamburger span {
  display: block; width: 22px; height: 2px;
  background: var(--navy); border-radius: 2px;
  transition: all var(--transition);
}
.hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Mobile drawer */
.mobile-nav {
  display: none; position: fixed; top: 68px; left: 0; right: 0; bottom: 0; z-index: 99;
}
.mobile-nav-overlay {
  position: absolute; inset: 0;
  background: rgba(27,20,100,0.3);
  opacity: 0; transition: opacity 0.3s ease;
}
.mobile-nav.open .mobile-nav-overlay { opacity: 1; }
.mobile-nav-drawer {
  position: absolute; top: 0; right: 0;
  width: min(320px, 85vw); height: 100%;
  background: var(--white);
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  padding: 24px; display: flex; flex-direction: column; gap: 8px;
  box-shadow: -4px 0 24px rgba(27,20,100,0.1);
}
.mobile-nav.open .mobile-nav-drawer { transform: translateX(0); }
.mobile-nav-link {
  display: block; padding: 14px 16px; border-radius: var(--radius-sm);
  font-size: 1.0625rem; font-weight: 500; color: var(--gray-800);
  transition: background var(--transition);
}
.mobile-nav-link:hover { background: var(--gray-50); }
.mobile-nav-link.signup {
  background: var(--navy); color: var(--white);
  text-align: center; font-weight: 600;
  margin-top: 8px; border-radius: var(--radius-md);
}

/* ===== HERO ===== */
.hero {
  padding: 140px 0 80px;
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; top: -200px; right: -200px;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(27,20,100,0.04) 0%, transparent 70%);
  border-radius: 50%;
}
.hero::after {
  content: '';
  position: absolute; bottom: -100px; left: -150px;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(255,217,48,0.08) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-content { position: relative; z-index: 1; text-align: center; max-width: 720px; margin: 0 auto; }
.hero h1 { margin-bottom: 20px; }
.hero h1 span { color: var(--teal); }
.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.1875rem);
  color: var(--gray-600); max-width: 600px; margin: 0 auto 40px;
}

/* ===== SEARCH BAR ===== */
.search-container { position: relative; z-index: 10; max-width: 820px; margin: 0 auto; }
.search-bar {
  display: flex; align-items: stretch;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  border: 2px solid transparent;
  transition: border-color var(--transition), box-shadow var(--transition);
  overflow: hidden;
}
.search-bar:focus-within {
  border-color: var(--navy);
  box-shadow: var(--shadow-xl), 0 0 0 4px rgba(27,20,100,0.08);
}
.search-field {
  flex: 1; display: flex; align-items: center; gap: 10px;
  padding: 16px 20px; border-right: 1px solid var(--gray-200);
  position: relative; min-width: 0;
}
.search-field:last-of-type { border-right: none; }
.search-field svg { flex-shrink: 0; color: var(--gray-400); }
.search-field input, .search-field select {
  border: none; outline: none; font-size: 0.9375rem;
  font-family: inherit; background: none;
  color: var(--gray-800); width: 100%;
}
.search-field input::placeholder, .search-field select { color: var(--gray-400); }
.search-field select option { color: var(--gray-800); }
.search-btn {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  padding: 16px 32px; background: var(--yellow);
  color: var(--navy); font-size: 1rem;
  font-weight: 700; border: none; cursor: pointer;
  white-space: nowrap; transition: all var(--transition);
  font-family: inherit;
}
.search-btn:hover { background: var(--yellow-hover); }
.search-btn:active { transform: scale(0.98); }
.search-btn svg { flex-shrink: 0; }

/* Autocomplete dropdown */
.autocomplete-dropdown {
  position: absolute; top: calc(100% + 8px); left: -2px; right: -2px;
  background: var(--white); border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg); border: 1px solid var(--gray-200);
  z-index: 20; display: none; overflow: hidden;
}
.autocomplete-dropdown.visible { display: block; animation: dropIn 0.15s ease; }
@keyframes dropIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}
.autocomplete-item {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 16px; cursor: pointer; transition: background var(--transition);
}
.autocomplete-item:hover, .autocomplete-item.highlighted { background: var(--gray-50); }
.autocomplete-item-icon {
  width: 36px; height: 36px; border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; font-size: 1rem;
}
.autocomplete-item-icon.specialty { background: rgba(10,186,181,0.1); color: var(--teal); }
.autocomplete-item-icon.condition { background: rgba(255,217,48,0.15); color: #D4A800; }
.autocomplete-item-icon.doctor { background: rgba(27,20,100,0.08); color: var(--navy); }
.autocomplete-item-text strong { color: var(--gray-800); font-weight: 600; }
.autocomplete-item-text span { font-size: 0.8125rem; color: var(--gray-400); margin-left: 6px; }

/* ===== SPECIALTIES ===== */
.specialties { padding: 96px 0; }
.specialties-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 20px; max-width: 780px; margin: 0 auto;
}
.specialty-card {
  display: flex; flex-direction: column; align-items: center;
  gap: 14px; padding: 28px 16px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  cursor: pointer; transition: all var(--transition);
  text-align: center;
}
.specialty-card:hover {
  border-color: var(--navy);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}
.specialty-card:active { transform: translateY(-2px); }
.specialty-icon {
  width: 56px; height: 56px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
  background: var(--gray-50);
  transition: background var(--transition);
}
.specialty-card:hover .specialty-icon { background: rgba(27,20,100,0.06); }
.specialty-card h3 { font-size: 0.9375rem; font-weight: 600; color: var(--navy); }
.specialty-card p { font-size: 0.8125rem; color: var(--gray-400); line-height: 1.5; }

/* ===== HOW IT WORKS ===== */
.how-it-works {
  padding: 96px 0;
  background: var(--gray-50);
}
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px; max-width: 900px; margin: 0 auto;
  position: relative;
}
.steps-grid::before {
  content: '';
  position: absolute; top: 40px; left: 15%; right: 15%;
  height: 2px; background: var(--gray-200);
}
.step-card { text-align: center; position: relative; z-index: 1; }
.step-number {
  width: 56px; height: 56px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.25rem; font-weight: 800;
  background: var(--white); color: var(--navy);
  border: 2px solid var(--navy);
  margin: 0 auto 24px;
  transition: all var(--transition);
}
.step-card:hover .step-number {
  background: var(--navy); color: var(--white);
}
.step-card h3 { margin-bottom: 10px; color: var(--navy); }
.step-card p { font-size: 0.9375rem; max-width: 260px; margin: 0 auto; }

/* ===== STATS ===== */
.stats {
  padding: 64px 0;
  background: var(--navy);
  position: relative;
  overflow: hidden;
}
.stats::before {
  content: '';
  position: absolute; top: -50%; right: -10%;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(255,217,48,0.1) 0%, transparent 70%);
  border-radius: 50%;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px; position: relative; z-index: 1;
}
.stat-item { text-align: center; }
.stat-value {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 800; color: var(--yellow);
  line-height: 1.2; margin-bottom: 6px;
}
.stat-label { color: rgba(255,255,255,0.75); font-size: 0.9375rem; font-weight: 500; }

/* ===== TESTIMONIALS ===== */
.testimonials { padding: 96px 0; }
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px; max-width: 960px; margin: 0 auto;
}
.testimonial-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 32px 28px;
  display: flex; flex-direction: column;
  transition: all var(--transition);
}
.testimonial-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}
.testimonial-stars { display: flex; gap: 3px; margin-bottom: 16px; }
.testimonial-stars svg { color: var(--yellow); }
.testimonial-text {
  font-size: 0.9375rem; color: var(--gray-600);
  line-height: 1.7; flex: 1; margin-bottom: 20px;
  font-style: italic;
}
.testimonial-author {
  display: flex; align-items: center; gap: 12px;
  border-top: 1px solid var(--gray-100); padding-top: 16px;
}
.testimonial-avatar {
  width: 40px; height: 40px; border-radius: 50%;
  background: var(--navy); color: var(--white);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 0.875rem;
}
.testimonial-name { font-weight: 600; color: var(--navy); font-size: 0.875rem; }
.testimonial-location { font-size: 0.8125rem; color: var(--gray-400); }

/* ===== MOBILE APP PROMO ===== */
.app-promo {
  padding: 96px 0;
  background: var(--gray-50);
}
.app-promo-inner {
  display: flex; align-items: center; gap: 64px;
  max-width: 960px; margin: 0 auto;
}
.app-promo-content { flex: 1; }
.app-promo-content h2 { margin-bottom: 16px; }
.app-promo-content > p { margin-bottom: 32px; font-size: 1.0625rem; }
.app-features {
  list-style: none; display: flex; flex-direction: column;
  gap: 14px; margin-bottom: 36px;
}
.app-features li {
  display: flex; align-items: center; gap: 12px;
  font-size: 0.9375rem; color: var(--gray-600);
}
.app-features li svg { color: var(--teal); flex-shrink: 0; }
.app-buttons { display: flex; gap: 12px; flex-wrap: wrap; }
.app-btn {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 12px 24px; border-radius: var(--radius-md);
  background: var(--navy); color: var(--white);
  font-weight: 600; font-size: 0.9375rem;
  transition: all var(--transition);
}
.app-btn:hover { background: var(--navy-light); transform: translateY(-1px); }
.app-btn svg { width: 22px; height: 22px; }
.app-promo-visual {
  flex: 0 0 280px; display: flex; align-items: center; justify-content: center;
}
.phone-mockup {
  width: 240px; height: 480px;
  background: var(--navy);
  border-radius: 32px;
  border: 4px solid var(--gray-800);
  position: relative;
  overflow: hidden;
  box-shadow: var(--shadow-xl);
}
.phone-screen {
  position: absolute; inset: 12px;
  background: var(--white);
  border-radius: 22px;
  display: flex; flex-direction: column;
  align-items: center; padding: 32px 16px;
}
.phone-logo {
  font-size: 0.875rem; font-weight: 800; color: var(--navy);
  margin-bottom: 16px;
}
.phone-search {
  width: 100%; height: 32px;
  background: var(--gray-100);
  border-radius: 8px; margin-bottom: 16px;
}
.phone-card {
  width: 100%; height: 56px;
  background: var(--gray-50);
  border-radius: 8px; margin-bottom: 10px;
  border: 1px solid var(--gray-200);
}
.phone-notch {
  position: absolute; top: 12px; left: 50%; transform: translateX(-50%);
  width: 80px; height: 22px; background: var(--navy);
  border-radius: 0 0 12px 12px; z-index: 2;
}

/* ===== FOOTER ===== */
.footer {
  padding: 64px 0 32px;
  background: var(--navy);
  color: rgba(255,255,255,0.7);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px; margin-bottom: 48px;
}
.footer-brand .logo { color: var(--white); margin-bottom: 16px; }
.footer-brand .logo-icon { background: var(--yellow); }
.footer-brand .logo-icon svg { color: var(--navy); }
.footer-tagline { font-size: 0.875rem; line-height: 1.6; }
.footer-col h4 {
  font-size: 0.8125rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.06em;
  color: rgba(255,255,255,0.4); margin-bottom: 16px;
}
.footer-col a {
  display: block; font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
  padding: 4px 0; transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 24px; text-align: center;
  font-size: 0.8125rem;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 900px) {
  .nav-links { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: block; pointer-events: none; }
  .mobile-nav.open { pointer-events: auto; }

  .search-bar { flex-direction: column; border-radius: var(--radius-md); }
  .search-field { border-right: none; border-bottom: 1px solid var(--gray-200); padding: 14px 16px; }
  .search-field:last-of-type { border-bottom: none; }
  .search-btn { padding: 16px; border-radius: 0 0 10px 10px; }
  .autocomplete-dropdown { left: 0; right: 0; }

  .specialties-grid { grid-template-columns: repeat(3, 1fr); gap: 12px; }
  .specialty-card { padding: 20px 12px; }
  .specialty-icon { width: 48px; height: 48px; }

  .steps-grid { grid-template-columns: 1fr; gap: 40px; max-width: 400px; }
  .steps-grid::before { display: none; }

  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 32px 16px; }

  .testimonials-grid { grid-template-columns: 1fr; max-width: 480px; }

  .app-promo-inner { flex-direction: column; text-align: center; gap: 48px; }
  .app-features { align-items: center; }
  .app-buttons { justify-content: center; }
  .app-promo-visual { flex: none; }

  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 480px) {
  .hero { padding: 120px 0 60px; }
  .hero h1 { font-size: 1.75rem; }
  .specialties-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; }
}

/* ===== ANIMATIONS ===== */
.fade-up {
  opacity: 0; transform: translateY(24px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}
.fade-up.visible { opacity: 1; transform: translateY(0); }
.fade-up.delay-1 { transition-delay: 0.1s; }
.fade-up.delay-2 { transition-delay: 0.2s; }
.fade-up.delay-3 { transition-delay: 0.3s; }

/* ===== FOCUS STYLES ===== */
:focus-visible {
  outline: 2px solid var(--navy);
  outline-offset: 2px;
}
.search-field input:focus-visible,
.search-field select:focus-visible {
  outline: none;
}

/* Counter animation */
@keyframes countPulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.05); }
  100% { transform: scale(1); }
}
.stat-value.animated { animation: countPulse 0.3s ease; }

/* Skeleton search bar shimmer */
@keyframes shimmer {
  to { background-position: -200% 0; }
}
</style>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
