<body>

<!-- ===== HEADER ===== -->
<header class="header" id="header">
  <div class="container header-inner">
    <a href="/" class="logo" aria-label="MedBook home">
      <div class="logo-icon">
        <svg viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2.5" stroke-linecap="round">
          <path d="M12 4v16M4 12h16"/>
        </svg>
      </div>
      MedBook
    </a>
    <nav class="nav-links" aria-label="Main navigation">
      <a href="#specialties" class="nav-link">Browse</a>
      <a href="#how-it-works" class="nav-link">Help</a>
      <a href="#" class="nav-link">Log In</a>
      <a href="#" class="nav-link signup">Sign Up</a>
    </nav>
    <button class="hamburger" id="hamburger" aria-label="Open navigation menu" aria-expanded="false" aria-controls="mobile-nav">
      <span></span><span></span><span></span>
    </button>
  </div>
</header>

<!-- Mobile Navigation -->
<div class="mobile-nav" id="mobile-nav" aria-hidden="true">
