<script>
// ===== HEADER SCROLL =====
const header = document.getElementById('header');
let lastScroll = 0;
window.addEventListener('scroll', () => {
  header.classList.toggle('scrolled', window.scrollY > 10);
}, { passive: true });

// ===== MOBILE MENU =====
const hamburger = document.getElementById('hamburger');
const mobileNav = document.getElementById('mobile-nav');
const mobileOverlay = document.getElementById('mobile-overlay');
const mobileLinks = mobileNav.querySelectorAll('.mobile-nav-link');

function toggleMobileMenu(open) {
  const isOpen = typeof open === 'boolean' ? open : !mobileNav.classList.contains('open');
  mobileNav.classList.toggle('open', isOpen);
  hamburger.classList.toggle('active', isOpen);
  hamburger.setAttribute('aria-expanded', isOpen);
  mobileNav.setAttribute('aria-hidden', !isOpen);
  document.body.style.overflow = isOpen ? 'hidden' : '';
  mobileLinks.forEach(l => l.setAttribute('tabindex', isOpen ? '0' : '-1'));
}

hamburger.addEventListener('click', () => toggleMobileMenu());
mobileOverlay.addEventListener('click', () => toggleMobileMenu(false));
mobileLinks.forEach(link => {
  link.addEventListener('click', () => toggleMobileMenu(false));
});
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && mobileNav.classList.contains('open')) toggleMobileMenu(false);
});

// ===== SEARCH AUTOCOMPLETE =====
const searchInput = document.getElementById('search-input');
const dropdown = document.getElementById('autocomplete-list');

const suggestions = [
  { text: 'Dentist', type: 'specialty', icon: 'specialty' },
  { text: 'Dermatologist', type: 'specialty', icon: 'specialty' },
  { text: 'Primary Care', type: 'specialty', icon: 'specialty' },
  { text: 'Psychiatrist', type: 'specialty', icon: 'specialty' },
  { text: 'Eye Doctor', type: 'specialty', icon: 'specialty' },
  { text: 'Orthopedic Surgeon', type: 'specialty', icon: 'specialty' },
  { text: 'Cardiologist', type: 'specialty', icon: 'specialty' },
  { text: 'Back pain', type: 'condition', icon: 'condition' },
  { text: 'Anxiety', type: 'condition', icon: 'condition' },
  { text: 'Acne treatment', type: 'condition', icon: 'condition' },
  { text: 'Headache', type: 'condition', icon: 'condition' },
  { text: 'Dr. Sarah Chen', type: 'doctor', icon: 'doctor' },
  { text: 'Dr. Michael Park', type: 'doctor', icon: 'doctor' },
];

const typeLabels = { specialty: 'Specialty', condition: 'Condition', doctor: 'Doctor' };
const typeIcons = {
  specialty: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>',
  condition: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 8v4M12 16h.01"/></svg>',
  doctor: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>',
};

let highlightedIndex = -1;

function renderDropdown(filtered) {
  if (!filtered.length) {
    dropdown.classList.remove('visible');
    searchInput.setAttribute('aria-expanded', 'false');
    return;
  }
  dropdown.innerHTML = filtered.map((item, i) => `
    <div class="autocomplete-item${i === highlightedIndex ? ' highlighted' : ''}" role="option" data-index="${i}" aria-selected="${i === highlightedIndex}">
      <div class="autocomplete-item-icon ${item.icon}">${typeIcons[item.icon]}</div>
      <div class="autocomplete-item-text"><strong>${highlightMatch(item.text, searchInput.value)}</strong><span>${typeLabels[item.type]}</span></div>
    </div>
  `).join('');
  dropdown.classList.add('visible');
  searchInput.setAttribute('aria-expanded', 'true');

  dropdown.querySelectorAll('.autocomplete-item').forEach(el => {
    el.addEventListener('mousedown', (e) => {
      e.preventDefault();
      searchInput.value = filtered[parseInt(el.dataset.index)].text;
      dropdown.classList.remove('visible');
      searchInput.setAttribute('aria-expanded', 'false');
    });
  });
}

function highlightMatch(text, query) {
  if (!query) return text;
  const idx = text.toLowerCase().indexOf(query.toLowerCase());
  if (idx === -1) return text;
  return text.slice(0, idx) + '<mark style="background:rgba(255,217,48,0.35);border-radius:2px;padding:0 1px">' + text.slice(idx, idx + query.length) + '</mark>' + text.slice(idx + query.length);
